    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    if (root->left == nullptr || root->right == nullptr) {
        TreeNode* temp = root->left ? root->left : root->right;
        if (temp == nullptr) {
            temp = root;
            root = nullptr;
        } else {
            *root = *temp;
        }
        delete temp;
    } else {
        TreeNode* temp = root->right;
        while (temp->left != nullptr) temp = temp->left;
        root->data = temp->data;
        avlDelete(root->right, temp->data);
    }
}

if (root == nullptr) return;

int balance = 0;
if (root->left != nullptr) balance += root->left->height;
if (root->right != nullptr) balance -= root->right->height;

if (balance > 1) {
    int leftBalance = 0;
    if (root->left->left != nullptr) leftBalance += root->left->left->height;
    if (root->left->right != nullptr) leftBalance -= root->left->right->height;

    if (leftBalance >= 0) {
        TreeNode* y = root->left;
        root->left = y->right;
        y->right = root;
        root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
        y->height = 1 + std::max((y->left ? y->left->height : 0), (y->right ? y->right->height : 0));
        root = y;
    } else {
        TreeNode* x = root->left->right;
        root->left->right = x->left;
        x->left = root->left;
        root->left->height = 1 + std::max((root->left->left ? root->left->left->height : 0), (root->left->right ? root->left->right->height : 0));
        x->height = 1 + std::max((x->left ? x->left->height : 0), (x->right ? x->right->height : 0));
        root->left = x;

        TreeNode* y = root->left;
        root->left = y->right;
        y->right = root;
        root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
        y->height = 1 + std::max((y->left ? y->left->height : 0), (y->right ? y->right->height : 0));
        root = y;
    }
} else if (balance < -1) {
    int rightBalance = 0;
    if (root->right->right != nullptr) rightBalance += root->right->right->height;
    if (root->right->left != nullptr) rightBalance -= root->right->left->height;

    if (rightBalance <= 0) {
        TreeNode* y = root->right;
        root->right = y->left;
        y->left = root;
        root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
        y->height = 1 + std::max((y->left ? y->left->height : 0), (y->right ? y->right->height : 0));
        root = y;
    } else {
        TreeNode* x = root->right->left;
        root->right->left = x->right;
        x->right = root->right;
        root->right->height = 1 + std::max((root->right->left ? root->right->left->height : 0), (root->right->right ? root->right->right->height : 0));
        x->height = 1 + std::max((x->left ? x->left->height : 0), (x->right ? x->right->height : 0));
