        TreeNode* y = root->right;
        root->right = y->left;
        y->left = root;
        root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
        y->height = 1 + std::max((y->left ? y->left->height : 0), (y->right ? y->right->height : 0));
        root = y;
    }
